from pathlib import Path
p=Path('js/dokuman-okuyucu.js'); s=p.read_text(encoding='utf-8')
def rep(a,b,label):
    global s
    c=s.count(a)
    if c!=1: raise SystemExit(f'{label}: expected 1 match, got {c}')
    s=s.replace(a,b,1)
rep("let A=null,pdf=null,wb=null,wordZoom=1;","let A=null,pdf=null,wb=null,wordZoom=1,pdfZoom=1;",'pdf zoom state')
rep(".dv3pdf{display:flex;flex-direction:column;align-items:center;gap:14px;padding:14px}.dv3pdf canvas{background:#fff;box-shadow:0 3px 15px #0008;max-width:100%;height:auto}",".dv3body.dv3pdfbody{overflow:hidden;display:flex;flex-direction:column;min-width:0;background:#565b61}.dv3pdftools{flex:0 0 auto;display:flex;align-items:center;justify-content:center;gap:6px;padding:7px;background:#20262d;border-bottom:1px solid #46505b}.dv3pdfviewport{flex:1 1 auto;min-height:0;overflow:auto;max-width:100%;padding:10px;box-sizing:border-box;overscroll-behavior:contain;touch-action:pan-x pan-y}.dv3pdfscene{position:relative;margin:0}.dv3pdfstage{position:absolute;left:0;top:0;transform-origin:top left;display:flex;flex-direction:column;align-items:flex-start;gap:18px}.dv3pdfpage{background:#fff;box-shadow:0 4px 18px #0008;outline:1px solid #d5d8dc;flex:0 0 auto}.dv3pdfpage canvas{display:block;background:#fff;max-width:none!important;height:auto}.dv3pdfpageinfo{margin-left:6px;min-width:66px;text-align:center;font-size:12px;font-weight:700;color:#e8edf2}",'pdf css')
old="async function pdfAc(){if(typeof pdfjsLib==='undefined')return fail('PDF.js bulunamadı.');status('PDF hazırlanıyor…');try{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';pdf=await pdfjsLib.getDocument({url:A.url,cMapUrl:'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/cmaps/',cMapPacked:true,standardFontDataUrl:'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/standard_fonts/',useSystemFonts:true,disableFontFace:false}).promise;A.body.innerHTML='<div class=\"dv3pdf\" id=\"dv3pdf\"></div>';const area=A.body.firstChild,dpr=Math.min(devicePixelRatio||1,2.25);for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),base=p.getViewport({scale:1}),cw=Math.min(Math.max(280,A.body.clientWidth-28),base.width*1.35),sc=cw/base.width,v=p.getViewport({scale:sc*dpr}),c=document.createElement('canvas');c.width=Math.round(v.width);c.height=Math.round(v.height);c.style.width=Math.round(base.width*sc)+'px';c.style.height=Math.round(base.height*sc)+'px';area.appendChild(c);await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise;}}catch(e){fail('PDF görüntülenemedi.',e.message);}}"
new="function pdfOlcekUygula(){if(!A)return;const st=A.body.querySelector('#dv3pdfStage'),scene=A.body.querySelector('#dv3pdfScene');if(!st||!scene)return;const w=Math.max(1,Number(st.dataset.naturalWidth)||st.scrollWidth||1),h=Math.max(1,Number(st.dataset.naturalHeight)||st.scrollHeight||1);st.style.transform=`scale(${pdfZoom})`;scene.style.width=Math.ceil(w*pdfZoom)+'px';scene.style.height=Math.ceil(h*pdfZoom)+'px';const l=A.body.querySelector('#dv3pdfZoomLabel');if(l)l.textContent=Math.round(pdfZoom*100)+'%';}\nfunction pdfZoomUygula(z){pdfZoom=Math.max(0.15,Math.min(4,z));pdfOlcekUygula();}\nfunction pdfSigdir(){if(!A)return;const wrap=A.body.querySelector('#dv3pdfViewport'),st=A.body.querySelector('#dv3pdfStage');if(!wrap||!st)return;st.style.transform='none';const w=Math.max(1,Number(st.dataset.naturalWidth)||st.scrollWidth||1);const uygun=Math.max(1,wrap.clientWidth-20);pdfZoom=Math.max(0.15,Math.min(1,uygun/w));pdfOlcekUygula();wrap.scrollTo({left:0,top:0,behavior:'auto'});}\nasync function pdfAc(){if(typeof pdfjsLib==='undefined')return fail('PDF.js bulunamadı.');status('PDF hazırlanıyor…');try{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';pdf=await pdfjsLib.getDocument({url:A.url,cMapUrl:'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/cmaps/',cMapPacked:true,standardFontDataUrl:'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/standard_fonts/',useSystemFonts:true,disableFontFace:false}).promise;pdfZoom=1;A.body.classList.add('dv3pdfbody');A.body.innerHTML='<div class=\"dv3pdftools\"><button class=\"dv3btn\" id=\"dv3pdfMinus\">−</button><button class=\"dv3btn\" id=\"dv3pdfFit\">Sığdır</button><span id=\"dv3pdfZoomLabel\" style=\"min-width:48px;text-align:center;font-weight:700\">100%</span><button class=\"dv3btn\" id=\"dv3pdfPlus\">+</button><span class=\"dv3pdfpageinfo\" id=\"dv3pdfPageInfo\">1 / '+pdf.numPages+'</span></div><div class=\"dv3pdfviewport\" id=\"dv3pdfViewport\"><div class=\"dv3pdfscene\" id=\"dv3pdfScene\"><div class=\"dv3pdfstage\" id=\"dv3pdfStage\"></div></div></div>';const stage=A.body.querySelector('#dv3pdfStage'),wrap=A.body.querySelector('#dv3pdfViewport'),dpr=Math.min(devicePixelRatio||1,2.25);let maxW=1,totalH=0;const sayfalar=[];for(let i=1;i<=pdf.numPages;i++){const p=await pdf.getPage(i),base=p.getViewport({scale:1}),v=p.getViewport({scale:dpr}),page=document.createElement('div'),c=document.createElement('canvas');page.className='dv3pdfpage';page.dataset.page=String(i);c.width=Math.round(v.width);c.height=Math.round(v.height);c.style.width=Math.round(base.width)+'px';c.style.height=Math.round(base.height)+'px';page.appendChild(c);stage.appendChild(page);sayfalar.push(page);maxW=Math.max(maxW,base.width);totalH+=base.height+(i<pdf.numPages?18:0);await p.render({canvasContext:c.getContext('2d'),viewport:v}).promise;}stage.dataset.naturalWidth=String(Math.ceil(maxW));stage.dataset.naturalHeight=String(Math.ceil(totalH));A.body.querySelector('#dv3pdfMinus').onclick=()=>pdfZoomUygula(pdfZoom-0.15);A.body.querySelector('#dv3pdfPlus').onclick=()=>pdfZoomUygula(pdfZoom+0.15);A.body.querySelector('#dv3pdfFit').onclick=pdfSigdir;const bilgi=A.body.querySelector('#dv3pdfPageInfo'),guncelle=()=>{if(!bilgi||!sayfalar.length)return;const y=wrap.scrollTop/Math.max(pdfZoom,0.01),i=sayfalar.findIndex(x=>(x.offsetTop+x.offsetHeight/2)>=y);bilgi.textContent=(Math.max(0,i)+1)+' / '+sayfalar.length;};wrap.addEventListener('scroll',guncelle,{passive:true});requestAnimationFrame(()=>requestAnimationFrame(()=>{pdfSigdir();guncelle();}));}catch(e){fail('PDF görüntülenemedi.',e.message);}}"
rep(old,new,'pdf viewer')
p.write_text(s,encoding='utf-8')

